import type { BoxProps, ElementConstructor, EngineInterface, On, RenderElement, RenderSurface, TextProps, Timer } from "claude-code";
import { blockingCdxCommand, blockingCdxRefusal, invokedRawEngine, nativeCdxCommand, nativeCdxRefusal, rawEngineRefusal } from "../guard";
import {
  afterPoll,
  afterToolCall,
  clearBuffer,
  initialDeliveryState,
  onPromptSubmit,
  onSubmitRefused,
  onTurnComplete,
  onTurnStart,
  type DeliveryState,
  type PendingEvent,
  type LiveSnapshot,
  type BandCell,
  bandTable,
  orderedRows,
} from "./delivery";
import {
  CDX_TOOL_PREFIX,
  MAX_PROCESS_TIMEOUT_MS,
  nativeToolResult, formatToolOutput,
  runFromCwd,
  SESSION_TOOLS,
  TOOL_NAMES,
  TOOLS,
  TOOLS_BY_NAME,
} from "./tools";

const NATIVE_TOOLS: ReadonlySet<string> = new Set(TOOL_NAMES);

let session = "";
let root = "";
let CDX: string[] = [];
let surface: RenderSurface | null = null;
let deliveryState: DeliveryState = initialDeliveryState();
let pollInFlight = false;
let pollTimer: Timer | undefined;
let outputSequence = 0;
const liveRef = { plugin: "cdx", key: "live" } as const;
const pollerRef = { plugin: "cdx", key: "poller" } as const;
const POLL_INTERVAL_MS = 2000;
const INSTANCE = `${Date.now()}-${Math.random()}`;
// Each refusal message is logged once; the poll runs every two seconds and
// a repeated log would flood the transcript.
const loggedRefusals = new Set<string>();

const BUDGET_SPENT_NOTICE = "cdx: the engine's per-session prompt budget is spent (50 prompts); lane events no longer wake an idle head. "
  + "They still land on the next tool result or typed prompt, and a fresh wake goes into the prompt box as a Tab suggestion. "
  + "A new session restores wakes.";

async function poll($: EngineInterface) {
  if (pollInFlight || !session || !root) {
    return;
  }
  pollInFlight = true;
  try {
    const eventsResult = await $.process.run(CDX.concat(["events", "--json", "--snapshot"]), {
      env: { CLAUDE_CODE_SESSION_ID: session },
      cwd: root,
    });

    let incomingEvents: PendingEvent[] = [];
    let snapshot: LiveSnapshot | undefined;
    if (eventsResult.exitCode === 0 && eventsResult.stdout.trim()) {
      try {
        const parsed = JSON.parse(eventsResult.stdout);
        if (parsed && Array.isArray(parsed.events)) {
          incomingEvents = parsed.events;
        }
        if (parsed && Array.isArray(parsed.rows) && typeof parsed.now === "number") {
          snapshot = { rows: parsed.rows, now: parsed.now };
        }
      } catch {
        // ignore malformed JSON
      }
    }
    if (snapshot) {
      await $.state.set(liveRef, snapshot);
    }

    // Everything the submit would carry, kept so a refused submit can put it
    // back. The submit is issued before any await so no turn can start in
    // between; it is not awaited because the prompt runs when the session is
    // idle and the poll must not wait for that.
    const drained = [...deliveryState.pending, ...incomingEvents];
    const outcome = afterPoll(deliveryState, incomingEvents);
    deliveryState = outcome.state;

    if (outcome.submit) {
      $.prompt.submit(outcome.submit).catch(async (error: unknown) => {
        const message = error instanceof Error ? error.message : String(error);
        deliveryState = onSubmitRefused(deliveryState, drained, message);
        if (loggedRefusals.has(message)) return;
        loggedRefusals.add(message);
        await $.ui.log(deliveryState.budgetSpent
          ? BUDGET_SPENT_NOTICE
          : `cdx: prompt not submitted, events kept for the next tool result: ${message}`);
      });
    }

    if (outcome.suggest && surface !== null) {
      await $.prompt.suggest(outcome.suggest).catch(() => undefined);
    }

    if (surface !== null) {
      for (const toastText of outcome.toasts) {
        await $.ui.toast(toastText, { timeoutMs: 8000 });
      }
    }
  } finally {
    pollInFlight = false;
  }
}

// A hot reload runs this module afresh with every variable above empty, and
// session.start does not always fire again, so each hook that needs the
// session context loads it here. The engine may not drop the old instance's
// timer either: the newest instance claims the poller in $.state and an
// older timer stops at its next tick.
async function ensure($: EngineInterface) {
  if (!session) session = await $.session.id();
  if (root) return;
  root = $.plugin.root;
  CDX = ["bun", `${root}/cdx.ts`];
  if (surface === null) surface = (await $.session.surfaces())[0] ?? null;
  await startPolling($);
}

// The host holds $.state for the session, so after a /clear or /resume the
// session the process moved to has no claim and the running timer would
// read that as a newer instance and stop. That hook starts the timer again.
async function startPolling($: EngineInterface) {
  pollTimer?.cancel();
  const timer = $.clock.every(POLL_INTERVAL_MS, async () => {
    if ((await $.state.get(pollerRef)).value !== INSTANCE) return timer.cancel();
    await ensure($);
    await poll($);
  });
  pollTimer = timer;
  await $.state.set(pollerRef, INSTANCE);
}

// The poll drains the feed every two seconds into the buffer, so the CLI
// alone would answer "nothing" while wake events sit in memory. The tool
// answers with the buffer first, then whatever the feed still held, and
// empties the buffer so the after-hook does not deliver it a second time.
function eventsToolResult(exitCode: number, stdout: string, stderr: string): string {
  const buffered = deliveryState.pending.map((e) => e.text);
  deliveryState = clearBuffer(deliveryState);
  let fresh: string[] = [];
  if (exitCode === 0 && stdout.trim()) {
    try {
      const parsed = JSON.parse(stdout);
      if (parsed && Array.isArray(parsed.events)) fresh = parsed.events.map((e: PendingEvent) => e.text);
    } catch {
      // malformed JSON: report the raw output below
    }
  }
  if (exitCode !== 0) return [...buffered, stdout].join("\n");
  const lines = [...buffered, ...fresh];
  return lines.length ? lines.join("\n") : "no pending events";
}

function bandLine(Box: ElementConstructor<BoxProps>, Text: ElementConstructor<TextProps>, cells: BandCell[]): RenderElement {
  return Box({ flexDirection: "row", children: cells.map((cell) =>
    Text({ ...(cell.color ? { color: cell.color } : {}), ...(cell.bold ? { bold: true } : {}), ...(cell.dim ? { dimColor: true } : {}),
      wrap: "truncate", children: cell.text })) });
}

export function register(on: On) {
  on("ui.render", { component: "AbovePrompt" }, async ($, e, next) => {
    const { value } = await $.state.get(liveRef);
    if (!value?.rows.length || e.props.hasSurvey) return next(e);
    const { Box, Text } = $.ui.resolve(e);
    // The margin is the blank line between the chat and the band.
    return Box({ flexDirection: "column", marginTop: 1, children: bandTable(orderedRows(value.rows), value.now, e.props.bodyColumns)
      .map((cells) => bandLine(Box, Text, cells)) });
  });

  on("ui.render", { component: "Pane" }, async ($, e, next) => {
    if (e.requestId !== "cdx-lanes") return next(e);
    const { value } = await $.state.get(liveRef);
    const { Box, Text } = $.ui.resolve(e);
    const rows = orderedRows(value?.rows ?? []);
    if (!rows.length) return Box({ flexDirection: "column", children: [Text({ children: "No running lanes or jobs" })] });
    const [header, ...lines] = bandTable(rows, value?.now ?? Date.now(), e.props.bodyColumns);
    return Box({ flexDirection: "column", children: [bandLine(Box, Text, header!), ...rows.flatMap((row, index) => [
      bandLine(Box, Text, lines[index]!),
      ...(row.transcript ?? []).map((text) => Text({ dimColor: true, wrap: "truncate",
        children: `  ${Array.from(text).slice(0, Math.max(0, e.props.bodyColumns - 3)).join("")}` })),
    ])] });
  });

  on("session.start", async ($, e, next) => {
    surface = e.surface;
    await ensure($);

    for (const tool of TOOLS) {
      await $.tool.register({
        name: tool.name,
        description: tool.description,
        inputSchema: tool.inputSchema,
      });
    }

    // /cdx is the user's skill, so the engine refuses that name. A refused
    // command must never stop the tools and the poll from starting.
    try {
      await $.command.register({
        name: "lanes",
        description: "Open live lanes, or forward arguments to cdx",
      });
    } catch (error) {
      await $.ui.log(`cdx: /lanes not registered: ${error instanceof Error ? error.message : String(error)}`);
    }

    // cdx elects the head only from sessions that drove it. A person at the
    // prompt claims the wakes at start; a -p run or an SDK host never does.
    const briefResult = await $.process.run(CDX.concat(e.isInteractive ? ["brief", "--head"] : ["brief"]), {
      env: { CLAUDE_CODE_SESSION_ID: session },
      cwd: root,
    });
    const briefText = briefResult.stdout.trim();
    if (briefText) {
      if (surface !== null) {
        await $.ui.log(briefText);
      }
      deliveryState = {
        ...deliveryState,
        pending: [...deliveryState.pending, { text: briefText, wake: false }],
      };
    }

    return next(e);
  });

  // A subagent's loop raises its own turn events with agentId set. Only the
  // head's turn decides whether the session is idle.
  on("turn.start", async ($, e, next) => {
    await ensure($);
    if (!(e as { agentId?: string }).agentId) deliveryState = onTurnStart(deliveryState);
    return next(e);
  });

  on("turn.complete", async ($, e, next) => {
    if (!e.agentId) deliveryState = onTurnComplete(deliveryState);
    return next(e);
  });

  on("command.run", { command: "lanes" }, async ($, e) => {
    await ensure($);
    if (!e.args.trim()) {
      const opened = await $.ui.open({ id: "cdx-lanes", title: "Lanes", focus: true });
      return { text: opened.isPlaced ? "Lanes pane opened" : `Lanes pane unavailable: ${opened.reason ?? "surface refused"}` };
    }
    const args = e.args.trim().split(/\s+/);
    const res = await $.process.run(CDX.concat(args), {
      env: { CLAUDE_CODE_SESSION_ID: session },
      cwd: root,
    });
    if (res.exitCode !== 0) {
      return { text: res.stderr || res.stdout || `exit ${res.exitCode}` };
    }
    return { text: res.stdout };
  });

  on("command.run", { command: ["clear", "resume"] }, async ($, e, next) => {
    const result = await next(e);
    await ensure($);
    session = await $.session.id();
    deliveryState = clearBuffer(deliveryState);
    await startPolling($);
    // The user typed /clear or /resume here, so this session keeps the head
    // under its new id.
    const briefResult = await $.process.run(CDX.concat(["brief", "--head"]), {
      env: { CLAUDE_CODE_SESSION_ID: session },
      cwd: root,
    });
    const briefText = briefResult.stdout.trim();
    if (briefText) {
      if (surface !== null) {
        await $.ui.log(briefText);
      }
      deliveryState = {
        ...deliveryState,
        pending: [{ text: briefText, wake: false }],
      };
    }
    return result;
  });

  on("tool.call", { tool: "Bash" }, async ($, e, next) => {
    const command = typeof (e as { command?: unknown }).command === "string"
      ? (e as { command: string }).command
      : "";
    const engine = invokedRawEngine(command);
    if (engine) {
      return { deny: rawEngineRefusal(engine) };
    }
    const blocking = blockingCdxCommand(command);
    if (blocking) {
      return { deny: blockingCdxRefusal(blocking) };
    }
    const native = nativeCdxCommand(command, NATIVE_TOOLS);
    if (native) {
      return { deny: nativeCdxRefusal(native) };
    }
    return next(e);
  });

  on("tool.call", async ($, e, next) => {
    await ensure($);
    const result = await next(e);
    if (result && "deny" in result && result.deny !== undefined) {
      return result;
    }
    if (e.agentId) {
      return result;
    }
    const outcome = afterToolCall(deliveryState);
    deliveryState = outcome.state;
    if (!outcome.context) {
      return result;
    }
    return {
      ...result,
      context: [...(result.context ?? []), outcome.context],
    };
  });

  on(
    "tool.call",
    { tool: /^mcp__cdx__/ },
    async ($, e) => {
    const toolName = e.tool.startsWith(CDX_TOOL_PREFIX)
      ? e.tool.slice(CDX_TOOL_PREFIX.length)
      : e.tool;
    const def = TOOLS_BY_NAME.get(toolName);
    if (!def) {
      return { isError: true, result: `unknown tool ${e.tool}` };
    }
    await ensure($);
    if (!session && SESSION_TOOLS.has(toolName)) {
      return { isError: true, result: `cdx ${toolName}: the engine gave no session id, so the lane or job would have no owner; retry, or run /clear` };
    }
    const toolInput = (e as { input?: Record<string, unknown> }).input ?? (e as Record<string, unknown>);
    let runSpec;
    try { runSpec = def.run(toolInput); }
    catch (error) { return { isError: true, result: String(error) }; }
    // Tool commands run where the head works, not in the plugin root: a
    // spawn --worktree without cd cuts from the caller's directory, and a
    // relative cd resolves against it.
    const procInit: {
      env: Record<string, string>;
      cwd: string;
      stdin?: string;
      timeoutMs: number;
    } = {
      env: { CLAUDE_CODE_SESSION_ID: session },
      cwd: await $.session.cwd(),
      timeoutMs: runSpec.timeoutMs ?? MAX_PROCESS_TIMEOUT_MS,
    };
    if (runSpec.stdin !== undefined) {
      procInit.stdin = runSpec.stdin;
    }
    let res;
    try {
      res = await runFromCwd(procInit.cwd, root, (path) => $.fs.exists(path),
        (cwd) => $.process.run(CDX.concat(runSpec.argv), { ...procInit, cwd }));
    } catch (error) {
      return { isError: true, result: `cdx ${runSpec.argv[0]}: ${error instanceof Error ? error.message : String(error)}` };
    }
    const stdout = toolName === "events" ? eventsToolResult(res.exitCode, res.stdout, res.stderr) : res.stdout;
    const text = await formatToolOutput(res.exitCode, stdout, res.stderr, async (content) => {
      const home = await $.env.get("CDX_HOME") || `${await $.env.get("HOME")}/.cdx`;
      const path = `${home}/logs/native-${session}-${Date.now()}-${++outputSequence}.log`;
      await $.fs.write(path, content);
      return path;
    });
    return nativeToolResult(res.exitCode, text);
  });

  on("prompt.submit", async ($, e, next) => {
    await ensure($);
    if (e.origin && e.origin.kind === "plugin" && e.origin.name === "cdx") {
      return next(e);
    }
    const outcome = onPromptSubmit(deliveryState);
    deliveryState = outcome.state;
    if (outcome.context) {
      return next({
        ...e,
        context: [...(e.context ?? []), outcome.context],
      });
    }
    return next(e);
  });
}

files.guard.ts:
// Raw engine guard: recognises a shell command that runs Codex or Antigravity
// directly instead of through cdx. Pure; shared by the Claude Code hooks
// module and by tests. No Bun or Node API here.

const WORK_VERBS = new Set(["e", "exec", "review", "resume", "fork", "cloud", "apply"]);
const CONTROL_WORDS = new Set(["if", "then", "elif", "else", "while", "until", "for", "do", "!", "{"]);
const WRAPPERS = new Set(["command", "exec", "env", "nice", "nohup", "sudo", "time"]);
const ASSIGNMENT = /^[A-Za-z_][A-Za-z0-9_]*=/;
const CODEX_GLOBAL_VALUE_OPTIONS = new Set([
  "-c", "--config", "--enable", "--disable", "--remote", "--remote-auth-token-env",
  "-i", "--image", "-m", "--model", "--local-provider", "-p", "--profile",
  "-s", "--sandbox", "-C", "--cd", "--add-dir", "-a", "--ask-for-approval",
]);
const CODEX_TERMINAL_OPTIONS = new Set(["-h", "--help", "-V", "--version", "--"]);
const AGY_HEADLESS_OPTIONS = new Set([
  "--print", "-p", "--prompt", "--prompt-interactive", "-i", "--input-format",
  "--continue", "-c", "--conversation",
]);

export type RawEngine = "gpt" | "gemini";

function stripQuotedSegments(command: string): string {
  return command.replace(/'[^']*'|"(?:\\.|[^"\\])*"/gs, "");
}

interface Heredoc {
  delimiter: string;
  quoted: boolean;
}

function heredocIn(line: string): Heredoc | undefined {
  let quote = "";
  for (let index = 0; index < line.length; index += 1) {
    const char = line[index]!;
    if (quote) {
      if (quote === '"' && char === "\\") index += 1;
      else if (char === quote) quote = "";
      continue;
    }
    if (char === "'" || char === '"') {
      quote = char;
      continue;
    }
    if (char !== "<" || line[index + 1] !== "<" || line[index + 2] === "<") continue;

    index += 2;
    if (line[index] === "-") index += 1;
    while (/\s/.test(line[index] ?? "")) index += 1;
    const delimiterQuote = line[index] === "'" || line[index] === '"' ? line[index]! : "";
    if (delimiterQuote) {
      const end = line.indexOf(delimiterQuote, index + 1);
      if (end < 0) return undefined;
      return { delimiter: line.slice(index + 1, end), quoted: true };
    }
    const delimiter = /^[^\s;&|<>]+/.exec(line.slice(index))?.[0];
    return delimiter ? { delimiter, quoted: false } : undefined;
  }
  return undefined;
}

function stripHeredocBodies(command: string, original: string): string {
  const kept: string[] = [];
  const lines = command.split("\n");
  const originalLines = original.split("\n");
  let heredoc: Heredoc | undefined;
  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index]!;
    const originalLine = originalLines[index] ?? line;
    if (heredoc) {
      if (originalLine.trim() === heredoc.delimiter) {
        heredoc = undefined;
      } else if (!heredoc.quoted) {
        for (const match of originalLine.matchAll(/\$\(([^()]*)\)|`([^`]*)`/g)) kept.push(match[0]!);
      }
      continue;
    }
    kept.push(line);
    heredoc = heredocIn(originalLine);
  }
  return kept.join("\n");
}

function codexWorkVerb(words: string[], binaryIndex: number): boolean {
  let index = binaryIndex + 1;
  while (index < words.length) {
    const word = words[index]!;
    if (CODEX_TERMINAL_OPTIONS.has(word)) return false;
    if (!word.startsWith("-")) return WORK_VERBS.has(word);
    index += 1;
    if (!word.includes("=") && CODEX_GLOBAL_VALUE_OPTIONS.has(word)) index += 1;
  }
  return false;
}

function skipRedirections(words: string[], start: number): number {
  let index = start;
  for (;;) {
    const match = /^\d*(?:<>|>>?|<<?|>&|<&)(.*)$/.exec(words[index] ?? "");
    if (!match) return index;
    index += 1;
    if (!match[1]) index += 1;
  }
}

function skipPrefixes(words: string[], start: number): number {
  let index = start;
  for (;;) {
    const before = index;
    index = skipRedirections(words, index);
    while (ASSIGNMENT.test(words[index] ?? "")) index += 1;
    if (index === before) return index;
  }
}

// The index of the binary a segment runs, past control words, assignments,
// redirections, and wrappers such as env, nice, or sudo.
function commandStart(words: string[]): number {
  let index = 0;
  while (CONTROL_WORDS.has(words[index] ?? "")) index += 1;
  index = skipPrefixes(words, index);

    while (WRAPPERS.has((words[index] ?? "").split("/").at(-1) ?? "")) {
      const wrapper = (words[index] ?? "").split("/").at(-1);
      index += 1;
      if (wrapper === "env") {
        while ((words[index] ?? "").startsWith("-")) {
          const option = words[index]!;
          index += 1;
          if (["-u", "--unset", "-C", "--chdir"].includes(option)) index += 1;
        }
        while (ASSIGNMENT.test(words[index] ?? "")) index += 1;
      } else if (wrapper === "sudo") {
        while ((words[index] ?? "").startsWith("-")) {
          const option = words[index]!;
          index += 1;
          if (["-C", "-g", "-h", "-p", "-r", "-t", "-u", "--chdir", "--group", "--host", "--prompt", "--role", "--type", "--user"].includes(option)) index += 1;
        }
      } else if (wrapper === "nice") {
        if (["-n", "--adjustment"].includes(words[index] ?? "")) index += 2;
      } else {
        while ((words[index] ?? "").startsWith("-")) index += 1;
      }
      index = skipPrefixes(words, index);
    }
  return index;
}

function invokedRawEngineIn(command: string): RawEngine | undefined {
  for (const match of command.matchAll(/\$\(([^()]*)\)|`([^`]*)`/gs)) {
    const nested = invokedRawEngineIn(match[1] ?? match[2] ?? "");
    if (nested) return nested;
  }
  const withoutArrayData = command.replace(/\b[A-Za-z_][A-Za-z0-9_]*=\([^)]*\)/gs, "");
  for (const segment of withoutArrayData.split(/[;&|()`\n]+/)) {
    const words = segment.trim().split(/\s+/).filter(Boolean);
    const index = commandStart(words);

    const binary = (words[index] ?? "").split("/").at(-1);
    if (binary === "codex" && codexWorkVerb(words, index)) return "gpt";
    if (binary === "agy") {
      const headless = words.slice(index + 1).some((word) => AGY_HEADLESS_OPTIONS.has(word.split("=")[0]!));
      if (headless) return "gemini";
    }
  }
  return undefined;
}

// Which engine a shell command would run directly, if any. Quoted text and
// heredoc bodies are ignored on the first pass; a second pass with quotes and
// backslash escapes collapsed catches agy "--print=x" and \agy --print=x.
export function invokedRawEngine(command: string): RawEngine | undefined {
  const unquoted = stripQuotedSegments(command);
  const collapsed = command.replace(/\\(.)/g, "$1").replace(/["']/g, "");
  return invokedRawEngineIn(stripHeredocBodies(unquoted, command))
    ?? invokedRawEngineIn(stripHeredocBodies(collapsed, command));
}

export function rawEngineRefusal(engine: RawEngine): string {
  return engine === "gemini"
    ? "Use cdx --engine gemini for Antigravity work. Run 'cdx help'."
    : "Use cdx for Codex work. Run 'cdx help'.";
}

// The head of a Claude Code session must never block on a lane or job (owner
// ruling 2026-09-15): the cdx mod wakes it with a [cdx] event. These are the
// shell shapes that block anyway.
export type BlockingCdx = "wait" | "status --watch" | "poll loop" | "sleep chain" | "tail -f";

const POLLING_SUBCOMMANDS = new Set([
  "status", "events", "report", "brief", "log", "tail", "questions", "feed",
]);

// The cdx subcommand a segment runs, as `cdx ...` or `bun .../cdx.ts ...`.
function cdxInvocation(words: string[], index: number): { subcommand: string; args: string[] } | undefined {
  const binary = (words[index] ?? "").split("/").at(-1) ?? "";
  let next = index + 1;

  if (binary === "bun" || binary === "node") {
    while ((words[next] ?? "").startsWith("-")) next += 1;
    if (words[next] === "run") {
      next += 1;
      while ((words[next] ?? "").startsWith("-")) next += 1;
    }
    const target = (words[next] ?? "").split("/").at(-1) ?? "";
    if (target !== "cdx.ts" && target !== "cdx") return undefined;
    next += 1;
  } else if (binary === "bunx" || binary === "npx") {
    while ((words[next] ?? "").startsWith("-")) next += 1;
    const target = (words[next] ?? "").split("/").at(-1) ?? "";
    if (target !== "cdx" && target !== "cdx.ts") return undefined;
    next += 1;
  } else if (binary !== "cdx" && binary !== "cdx.ts") {
    return undefined;
  }

  while ((words[next] ?? "").startsWith("-")) {
    next += ["-C", "--cd", "--cwd"].includes(words[next]!) ? 2 : 1;
  }
  const subcommand = words[next];
  return subcommand === undefined ? undefined : { subcommand, args: words.slice(next + 1) };
}

function isStatusWatch(invocation: { subcommand: string; args: string[] }): boolean {
  if (invocation.subcommand !== "status") return false;
  return invocation.args.some((arg) => arg === "--watch" || arg.startsWith("--watch=") || arg === "-w" || arg.startsWith("-w="));
}

function isTailFollow(invocation: { subcommand: string; args: string[] }): boolean {
  if (invocation.subcommand !== "tail") return false;
  return invocation.args.some((arg) => arg === "-f" || arg === "--follow" || arg.startsWith("--follow=") || /^-[a-zA-Z]*f/.test(arg));
}

function hasFollowFlag(args: string[]): boolean {
  return args.some((arg) => arg === "-f" || arg === "-F" || arg === "--follow" || arg.startsWith("--follow=") || /^-[a-zA-Z]*[fF]/.test(arg));
}

function isCdxLogPath(arg: string): boolean {
  if (/(?:\.cdx|CDX_HOME|CDX_STATE_HOME)[/\\](?:logs[/\\])?.*(?:\.log|\.jsonl)\b/i.test(arg)) return true;
  if (/(?:^|[/\\])\.cdx[/\\]logs\b/i.test(arg)) return true;
  if (arg === "__CDX_LOG__" || /\$\{(?:CDX_HOME|CDX_STATE_HOME)\}[/\\]logs[/\\]/.test(arg)) return true;
  return false;
}

function watchCdxTarget(words: string[], index: number): { subcommand: string; args: string[] } | undefined {
  let next = index + 1;
  while (next < words.length) {
    const word = words[next]!;
    if (word === "-n" || word === "--interval") {
      next += 2;
      continue;
    }
    if (word.startsWith("-")) {
      next += 1;
      continue;
    }
    break;
  }
  return cdxInvocation(words, next);
}

type LoopKind = "while" | "until" | "for-finite-batch" | "for-poll";

function loopKindAtStart(words: string[]): LoopKind | undefined {
  for (let i = 0; i < words.length; i += 1) {
    const word = words[i]!;
    if (word === "while") return "while";
    if (word === "until") return "until";
    if (word === "for") {
      const items = words.slice(i + 3);
      if (words[i + 2] === "in" && items.length > 0 && items.every((item) => !/[$`{}]/.test(item))) {
        return "for-finite-batch";
      }
      return "for-poll";
    }
    if (!CONTROL_WORDS.has(word) && !ASSIGNMENT.test(word)) break;
  }
  return undefined;
}

function hasDoneKeywordAtStart(words: string[]): boolean {
  for (let i = 0; i < words.length; i += 1) {
    const word = words[i]!;
    if (word === "done") return true;
    if (!CONTROL_WORDS.has(word) && !ASSIGNMENT.test(word)) break;
  }
  return false;
}

function isCdxLogSubstitution(sub: string): boolean {
  return /\bcdx(?:\.ts)?\s+log\b/.test(sub);
}

function extractSubstitutions(text: string): string[] {
  const result: string[] = [];
  for (const match of text.matchAll(/\$\(([^()]*)\)|(?:\\`|`)([^`]*?)(?:\\`|`)/gs)) {
    const inner = (match[1] ?? match[2] ?? "").replace(/^\\+/, "").replace(/\\+$/, "").trim();
    if (inner) result.push(inner);
  }
  return result;
}

function replaceUnquotedSubstitutions(text: string): string {
  return text.replace(/\$\(([^()]*)\)|(?:\\`|`)([^`]*?)(?:\\`|`)/gs, (_, p1, p2) => {
    const inner = (p1 ?? p2 ?? "").replace(/^\\+/, "").replace(/\\+$/, "").trim();
    if (!inner) return " ";
    return isCdxLogSubstitution(inner) ? ` __CDX_LOG__ ; ${inner} ; ` : ` ; ${inner} ; `;
  });
}

function stripQuotedPreservingSubstitutions(command: string): string {
  const withoutSingle = command.replace(/'([^']*)'/gs, (_, content: string) => isCdxLogPath(content) ? " __CDX_LOG__ " : " ");
  const withoutDouble = withoutSingle.replace(/"((?:\\.|[^"\\])*)"/gs, (_, content: string) => {
    const subs = extractSubstitutions(content);
    if (subs.length > 0) {
      const hasLog = subs.some(isCdxLogSubstitution);
      const prefix = hasLog ? " __CDX_LOG__ ; " : " ";
      return `${prefix} ; ${subs.join(" ; ")} ; `;
    }
    return isCdxLogPath(content) ? " __CDX_LOG__ " : " ";
  });
  return replaceUnquotedSubstitutions(withoutDouble);
}

export function blockingCdxCommand(command: string): BlockingCdx | undefined {
  const clean = stripHeredocBodies(stripQuotedPreservingSubstitutions(command), command);
  const loopStack: LoopKind[] = [];
  let cdxInLoop = false;
  let hasSleepOutsideLoop = false;
  let hasPollingOutsideLoop = false;

  for (const segment of clean.split(/[;&|()\n]+/)) {
    const words = segment.trim().split(/\s+/).filter(Boolean);
    if (words.length === 0) continue;

    const loopKind = loopKindAtStart(words);
    if (loopKind) {
      loopStack.push(loopKind);
    }

    const start = commandStart(words);
    const binary = (words[start] ?? "").split("/").at(-1) ?? "";

    if (binary === "watch") {
      const target = watchCdxTarget(words, start);
      if (target) {
        if (isStatusWatch(target) || target.subcommand === "status") return "status --watch";
        if (target.subcommand === "wait") return "wait";
        if (POLLING_SUBCOMMANDS.has(target.subcommand)) return "poll loop";
      }
    } else if (binary === "tail") {
      const tailArgs = words.slice(start + 1);
      if (hasFollowFlag(tailArgs)) {
        if (tailArgs.some(isCdxLogPath) || (/cdx\s+log\b/.test(command) && tailArgs.some((arg) => arg.includes("$")))) {
          return "tail -f";
        }
      }
    } else if (binary === "sleep") {
      if (loopStack.length === 0) {
        hasSleepOutsideLoop = true;
      }
    } else {
      const invocation = cdxInvocation(words, start);
      if (invocation) {
        if (invocation.subcommand === "wait") return "wait";
        if (isStatusWatch(invocation)) return "status --watch";
        if (isTailFollow(invocation)) return "tail -f";
        if (loopStack.length > 0) {
          const isFiniteBatch = loopStack.every((k) => k === "for-finite-batch")
            && (!POLLING_SUBCOMMANDS.has(invocation.subcommand) || invocation.subcommand === "report" || invocation.subcommand === "brief");
          if (!isFiniteBatch) {
            cdxInLoop = true;
          }
        } else if (POLLING_SUBCOMMANDS.has(invocation.subcommand)) {
          hasPollingOutsideLoop = true;
        }
      }
    }

    if (hasDoneKeywordAtStart(words)) {
      loopStack.pop();
    }
  }

  if (cdxInLoop) return "poll loop";
  if (hasSleepOutsideLoop && hasPollingOutsideLoop) return "sleep chain";
  return undefined;
}

export function blockingCdxRefusal(kind: BlockingCdx): string {
  const what = kind === "wait"
    ? "cdx wait"
    : kind === "status --watch"
      ? "cdx status --watch"
      : kind === "sleep chain"
        ? "a sleep chain polling cdx"
        : kind === "tail -f"
          ? "tail -f on cdx logs"
          : "a shell loop polling cdx";
  return `${what} blocks the head; the head never blocks on a lane or job (owner ruling 2026-09-15). `
    + "End your turn: a [cdx] event wakes you when it finishes, asks, stalls, or fails. "
    + "To check right now, call mcp__cdx__status or mcp__cdx__events. "
    + "If nothing else is pending, ending the turn is the correct move, not a wait.";
}

// Inside Claude Code every cdx command with a native tool goes through the
// plugin: the tool runs in the session directory and its result lands in
// the transcript, while a shell invocation guesses a cwd and drifts with the
// last `cd`. The shell form stays for lanes and terminals outside Claude Code.
export function nativeCdxCommand(command: string, nativeTools: ReadonlySet<string>): string | undefined {
  const clean = stripHeredocBodies(stripQuotedPreservingSubstitutions(command), command);
  for (const segment of clean.split(/[;&|()\n]+/)) {
    const words = segment.trim().split(/\s+/).filter(Boolean);
    if (words.length === 0) continue;
    const invocation = cdxInvocation(words, commandStart(words));
    if (invocation && nativeTools.has(invocation.subcommand)) return invocation.subcommand;
  }
  return undefined;
}

export function nativeCdxRefusal(subcommand: string): string {
  return `cdx ${subcommand} from the shell is refused inside Claude Code; call mcp__cdx__${subcommand} instead. `
    + "The native tool runs in the session directory and keeps the result in the transcript; "
    + "the shell form is for lanes and terminals outside Claude Code.";
}

